package com.opsdemo.operations;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.BitmapFactory;
import android.text.InputType;
import android.view.View;
import android.widget.*;
import org.json.*;
import java.net.HttpCookie;
import java.util.*;
import java.util.concurrent.*;
import java.time.LocalDate;
import com.google.firebase.FirebaseApp;
import com.google.firebase.messaging.FirebaseMessaging;

/** Two production tabs and one quantity confirmation; no customer contacts or financial data. */
public final class ProductionActivity extends Activity {
 private ApiClient api;private SessionStore sessions;private boolean signed,busy,arabic=true;private String tab="LIMITED";
 private JSONArray work=new JSONArray();private LinearLayout root,body;private TextView status;private final ExecutorService executor=Executors.newSingleThreadExecutor();private final ExecutorService photos=Executors.newFixedThreadPool(2);private final Handler handler=new Handler(Looper.getMainLooper());
 private final Runnable poll=new Runnable(){public void run(){if(signed&&!busy)refresh();handler.postDelayed(this,30000);}};
 private String tr(String en,String ar){return arabic?ar:en;}
 private String number(String value){try{return new java.math.BigDecimal(value).stripTrailingZeros().toPlainString();}catch(Exception error){return value;}}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextColor(Color.BLACK);t.setTextSize(size);t.setPadding(dp(8),dp(10),dp(8),dp(10));return t;}
 private Button button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setMinHeight(dp(52));b.setOnClickListener(v->{if(!busy)action.run();});return b;}
 private void shell(){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(12),0,dp(12),0);root.setBackgroundColor(0xfff5f5f5);root.setLayoutDirection(arabic?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(dp(12)+i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),dp(12)+i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});
  LinearLayout header=new LinearLayout(this);ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.company_logo);logo.setContentDescription("OPSDEMO Coffee Roasters");logo.setScaleType(ImageView.ScaleType.FIT_CENTER);header.addView(logo,new LinearLayout.LayoutParams(dp(48),dp(48)));header.addView(text(tr("Production","الإنتاج"),20),new LinearLayout.LayoutParams(0,-2,1));header.addView(button(arabic?"English":"العربية",()->{arabic=!arabic;getPreferences(0).edit().putBoolean("arabic",arabic).apply();if(signed)home();else login();}));if(signed)header.addView(button(tr("Sign out","خروج"),this::logout));root.addView(header);status=text("",15);status.setTextColor(0xffb42318);root.addView(status);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);root.requestApplyInsets();}
 @Override public void onCreate(Bundle b){super.onCreate(b);arabic=getPreferences(0).getBoolean("arabic",true);api=new ApiClient(BuildConfig.SERVER_URL);sessions=new SessionStore(this,api.origin.toString());ProductionMessaging.channel(this);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},4);restore();}
 private interface Job{JSONObject run()throws Exception;}
 private interface Done{void accept(JSONObject data)throws Exception;}
 private void run(Job job,Done done){if(busy)return;busy=true;executor.submit(()->{try{JSONObject result=job.run();runOnUiThread(()->{if(isDestroyed())return;busy=false;try{done.accept(result);}catch(Exception e){status.setText(tr("Refresh and try again.","حدّث القائمة وحاول مرة أخرى."));}});}catch(Exception error){runOnUiThread(()->{if(isDestroyed())return;busy=false;if(error instanceof ApiClient.ApiException&&(((ApiClient.ApiException)error).status==401||((ApiClient.ApiException)error).status==403)){sessions.clear();api.clear();login();}status.setText(error instanceof ApiClient.ApiException?error.getMessage():tr("Connection lost. Refresh before retrying.","انقطع الاتصال. حدّث القائمة قبل إعادة المحاولة."));});}});}
 private boolean authorized(JSONObject profile){JSONArray roles=profile.optJSONArray("roles");return roles!=null&&roles.length()==1&&roles.optString(0).equals("Production");}
 private void restore(){JSONObject saved=sessions.load();if(saved==null){login();return;}try{api.restoreSession(saved.getString("token"),saved.getLong("expires"));}catch(Exception e){login();return;}shell();body.addView(text(tr("Connecting…","جارٍ الاتصال…"),22));body.addView(button(tr("Retry","إعادة المحاولة"),this::restore));body.addView(button(tr("Use another account","حساب آخر"),this::logout));run(()->api.get("/api/v1/auth/me/"),profile->{if(!authorized(profile)){sessions.clear();api.clear();login();return;}signed=true;home();registerPush();refresh();});}
 private void login(){signed=false;sessions.clear();api.clear();shell();body.addView(text(tr("Sign in once","سجّل الدخول مرة واحدة"),24));EditText user=new EditText(this);user.setHint(tr("Username","اسم المستخدم"));user.setSingleLine(true);body.addView(user);EditText password=new EditText(this);password.setHint(tr("Password","كلمة المرور"));password.setInputType(129);password.setSaveEnabled(false);body.addView(password);body.addView(button(tr("Sign in","دخول"),()->{String name=user.getText().toString().trim(),secret=password.getText().toString();if(name.isEmpty()||secret.isEmpty())return;password.setText("");run(()->api.post("/api/v1/auth/login/",new JSONObject().put("username",name).put("password",secret).put("remember_me",true)),profile->{if(!authorized(profile)){status.setText(tr("Use your Production account.","استخدم حساب الإنتاج."));api.clear();return;}boolean remembered=false;for(HttpCookie c:api.cookieSnapshot())if(c.getName().equals("sessionid")&&c.getMaxAge()>0){sessions.save(c.getValue(),System.currentTimeMillis()+Math.min(c.getMaxAge(),30L*86400)*1000);remembered=true;break;}signed=true;home();if(!remembered)status.setText(tr("Sign-in could not be remembered.","تعذر حفظ تسجيل الدخول."));registerPush();refresh();});}));}
 private void registerPush(){if(FirebaseApp.getApps(this).isEmpty())return;FirebaseMessaging.getInstance().getToken().addOnSuccessListener(token->{getSharedPreferences("production-push",0).edit().putString("token",token).apply();executor.submit(()->{try{api.post("/api/v1/production/device/",new JSONObject().put("token",token));}catch(Exception ignored){}});});}
 private void logout(){sessions.clear();if(!FirebaseApp.getApps(this).isEmpty())FirebaseMessaging.getInstance().deleteToken();executor.submit(()->{try{api.post("/api/v1/auth/logout/",new JSONObject());}catch(Exception ignored){}api.clear();runOnUiThread(()->{if(!isDestroyed()){busy=false;login();}});});}
 private void refresh(){run(()->api.get("/api/v1/production/work/"),data->{work=data.getJSONArray("work");JSONArray notices=data.optJSONArray("notices");if(notices!=null){android.content.SharedPreferences seen=getSharedPreferences("production-notices",0);for(int i=notices.length()-1;i>=0;i--){JSONObject note=notices.getJSONObject(i);String id=note.getString("id");if(!seen.getBoolean(id,false)){ProductionMessaging.notifyWork(this,id,note.optString("kind").equals("LIMITED")?tr("A limited-edition box needs making","مطلوب تجهيز علبة الإصدار المحدود"):tr("A product is running short","مطلوب إنتاج كمية من منتج ناقص"));seen.edit().putBoolean(id,true).apply();}}}home();});}
 private void home(){shell();LinearLayout tabs=new LinearLayout(this);for(String kind:new String[]{"LIMITED","SHORTAGE"}){Button b=button(kind.equals("LIMITED")?tr("Limited edition boxes","علب الإصدار المحدود"):tr("Other shortages","النواقص الأخرى"),()->{tab=kind;home();});b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(tab.equals(kind)?Color.BLACK:Color.WHITE));b.setTextColor(tab.equals(kind)?Color.WHITE:Color.BLACK);tabs.addView(b,new LinearLayout.LayoutParams(0,dp(64),1));}body.addView(tabs);body.addView(button(tr("Refresh","تحديث"),this::refresh));if(FirebaseApp.getApps(this).isEmpty())body.addView(text(tr("Trial alerts work while this app is open. Company push setup is pending.","التنبيهات التجريبية تعمل والتطبيق مفتوح. إعداد تنبيهات الشركة لم يكتمل بعد."),14));
  int count=0;for(int i=0;i<work.length();i++){JSONObject row=work.optJSONObject(i);if(row==null||!row.optString("kind").equals(tab))continue;count++;
   LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(12),dp(10),dp(12),dp(18));card.setBackgroundColor(Color.WHITE);body.addView(card);card.addView(text(row.optString("name"),21));card.addView(text(row.optString("order")+" · "+row.optString("location"),15));String path=row.optString("photo_url");if(!path.isEmpty()){ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);card.addView(image,new LinearLayout.LayoutParams(-1,dp(130)));photos.submit(()->{try{byte[] bytes=api.photo(path);android.graphics.Bitmap photo=BitmapFactory.decodeByteArray(bytes,0,bytes.length);runOnUiThread(()->{if(!isDestroyed())image.setImageBitmap(photo);});}catch(Exception ignored){}});}
   card.addView(text(tr("Made: ","تم إنتاج: ")+number(row.optString("made"))+tr(" · Remaining: "," · المتبقي: ")+number(row.optString("remaining")),18));EditText quantity=new EditText(this);quantity.setInputType(InputType.TYPE_CLASS_NUMBER);quantity.setHint(tr("How many did you make?","أنتجت كام؟"));card.addView(quantity);card.addView(button(tr("Record made","تسجيل الإنتاج"),()->confirm(row,quantity.getText().toString())));
  }if(count==0)body.addView(text(tr("Nothing to make here.","لا توجد متجر تجريبي إنتاج هنا."),22));}
 private void confirm(JSONObject row,String quantity){if(!quantity.matches("[0-9]+")||new java.math.BigDecimal(quantity).signum()<=0){status.setText(tr("Enter a positive quantity.","أدخل كمية أكبر من صفر."));return;}
  String key=UUID.randomUUID().toString();LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(dp(18),dp(12),dp(18),dp(12));form.addView(text(row.optString("name")+" × "+quantity,20));TextView error=text("",15);error.setTextColor(0xffb42318);form.addView(error);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(tr("Confirm production","تأكيد الإنتاج")).setView(form).setNegativeButton(tr("Back","رجوع"),null).setPositiveButton(tr("Confirm","تأكيد"),null).create();dialog.show();dialog.getButton(-1).setOnClickListener(v->{if(busy)return;busy=true;dialog.setCancelable(false);executor.submit(()->{try{JSONObject payload=new JSONObject().put("version",row.getInt("version")).put("quantity",quantity).put("command_key",key).put("reference","P-"+LocalDate.now()+"-"+key.substring(0,8));api.post("/api/v1/production/work/"+row.getString("id")+"/made/",payload);runOnUiThread(()->{busy=false;dialog.dismiss();refresh();});}catch(Exception e){runOnUiThread(()->{busy=false;dialog.setCancelable(true);error.setText(e instanceof ApiClient.ApiException?e.getMessage():tr("Connection lost. Retry this confirmation or go back and refresh.","انقطع الاتصال. حاول تأكيد نفس العملية أو ارجع وحدّث القائمة."));});}});});}
 @Override protected void onResume(){super.onResume();handler.postDelayed(poll,30000);if(signed&&!busy)refresh();}
 @Override protected void onPause(){handler.removeCallbacks(poll);super.onPause();}
 @Override protected void onDestroy(){handler.removeCallbacks(poll);executor.shutdownNow();photos.shutdownNow();super.onDestroy();}
}
